DROP TABLE IF EXISTS `concerns`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `concerns` (
  `concern_id` int(11) NOT NULL AUTO_INCREMENT,
  `ticket_id` varchar(50) NOT NULL,
  `student_id` int(11) NOT NULL,
  `is_anonymous` tinyint(1) NOT NULL DEFAULT 0,
  `category_id` int(11) NOT NULL,
  `status_id` int(11) NOT NULL DEFAULT 1,
  `assigned_admin_id` int(11) DEFAULT NULL,
  `title` varchar(255) NOT NULL,
  `description` text NOT NULL,
  `attachment_path` varchar(255) DEFAULT NULL,
  `priority` enum('Critical','High','Medium','Low') DEFAULT 'Medium',
  `ai_urgency_score` int(11) DEFAULT 50,
  `ai_reasons` text DEFAULT NULL,
  `ai_engine` varchar(20) DEFAULT NULL,
  `ai_fix_hours` smallint(6) DEFAULT NULL,
  `ai_fix_note` varchar(160) DEFAULT NULL,
  `ai_suggested_category_id` int(11) DEFAULT NULL,
  `sla_hours` int(11) DEFAULT 72,
  `sla_due_at` datetime DEFAULT NULL,
  `sla_alert_level` enum('none','at_risk','breached') NOT NULL DEFAULT 'none',
  `first_response_at` datetime DEFAULT NULL,
  `resolved_at` datetime DEFAULT NULL,
  `reopen_count` tinyint(4) NOT NULL DEFAULT 0,
  `last_reopened_at` datetime DEFAULT NULL,
  `withdrawn_at` datetime DEFAULT NULL,
  `withdraw_reason` varchar(255) DEFAULT NULL,
  `edited_at` datetime DEFAULT NULL,
  `edit_count` tinyint(4) NOT NULL DEFAULT 0,
  `is_rrt_alert` tinyint(1) DEFAULT 0,
  `date_submitted` datetime DEFAULT current_timestamp(),
  `updated_at` datetime DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `archived_at` datetime DEFAULT NULL,
  `archived_by` int(11) DEFAULT NULL,
  PRIMARY KEY (`concern_id`),
  UNIQUE KEY `ticket_id` (`ticket_id`),
  KEY `ticket_id_2` (`ticket_id`),
  KEY `student_id` (`student_id`),
  KEY `category_id` (`category_id`),
  KEY `status_id` (`status_id`),
  KEY `priority` (`priority`),
  KEY `idx_concerns_sla_due` (`sla_due_at`),
  KEY `idx_concerns_date_submitted` (`date_submitted`),
  KEY `idx_concerns_resolved_at` (`resolved_at`),
  KEY `idx_concerns_assigned` (`assigned_admin_id`),
  KEY `idx_concerns_archived` (`archived_at`),
  CONSTRAINT `fk_concern_assigned_admin` FOREIGN KEY (`assigned_admin_id`) REFERENCES `administrators` (`admin_id`) ON DELETE SET NULL,
  CONSTRAINT `fk_concern_category` FOREIGN KEY (`category_id`) REFERENCES `categories` (`category_id`),
  CONSTRAINT `fk_concern_status` FOREIGN KEY (`status_id`) REFERENCES `statuses` (`status_id`),
  CONSTRAINT `fk_concern_student` FOREIGN KEY (`student_id`) REFERENCES `students` (`student_id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=16 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
