INSERT INTO `concerns` VALUES (1,'SCF-2026-001',1,0,3,2,1,'ID printing machine not working','The card printer in the student services office is malfunctioning and jamming cards.',NULL,'Low',35,NULL,NULL,NULL,NULL,NULL,120,'2026-11-11 10:32:21','at_risk','2026-11-06 15:32:21',NULL,0,NULL,NULL,NULL,NULL,0,0,'2026-11-06 10:32:21','2026-11-10 15:39:38',NULL,NULL),(2,'SCF-2026-002',1,0,1,3,1,'Canteen foods are always cold','Food served in the central canteen warmers is frequently served cold during lunch breaks.',NULL,'Low',28,NULL,NULL,NULL,NULL,NULL,120,'2026-11-08 12:32:21','none','2026-11-03 18:32:21','2026-11-04 16:32:21',0,NULL,NULL,NULL,NULL,0,0,'2026-11-03 12:32:21','2026-11-09 18:32:21',NULL,NULL),(3,'SCF-2026-003',1,0,2,3,3,'Clarification about exam schedule','There is an overlap between IT 312 and CS 311 mid-term examination rooms.',NULL,'Medium',52,NULL,NULL,NULL,NULL,NULL,72,'2026-11-08 04:32:21','none','2026-11-06 00:32:21','2026-11-06 00:32:21',0,NULL,NULL,NULL,NULL,0,0,'2026-11-05 04:32:21','2026-11-09 18:32:21',NULL,NULL),(4,'SCF-2026-004',1,0,3,1,NULL,'Internet connection issue in Library','Wi-Fi connection drops every 5 minutes on the 2nd floor library study area.',NULL,'Medium',58,NULL,NULL,NULL,NULL,NULL,72,'2026-11-09 10:32:21','breached',NULL,NULL,0,NULL,NULL,NULL,NULL,0,0,'2026-11-06 10:32:21','2026-11-09 18:35:45',NULL,NULL),(5,'SCF-2026-005',1,0,1,2,1,'Broken chairs in classroom Lab 2','There are several broken chairs in our classroom Lab 2. It is uncomfortable and unsafe to use. Please kindly address this issue. Thank you.',NULL,'High',78,NULL,NULL,NULL,NULL,NULL,48,'2026-11-10 12:32:21','breached','2026-11-08 16:32:21',NULL,0,NULL,NULL,NULL,NULL,0,0,'2026-11-08 12:32:21','2026-11-10 15:39:38',NULL,NULL),(6,'SCF-2026-006',6,0,2,3,3,'Online class attendance error','Attendance in LMS for May 2 meeting marked absent despite submitting activity on time.',NULL,'Medium',45,NULL,NULL,NULL,NULL,NULL,72,'2026-11-03 14:32:21','none','2026-11-01 20:32:21'