INSERT INTO `feedback` VALUES (1,1,NULL,'Juan Dela Cruz','juan.delacruz@student.com','System Feedback','Very convenient concern tracking system','The real-time status tracking and transparent administrator replies help us follow up on issues without visiting offices physically.',5,'Thank you, Juan! We are glad the tracking helps. We will keep improving it based on student feedback.',1,'2026-11-07 06:32:21','2026-11-06 20:32:21'),(2,2,NULL,'Maria Santos','maria.santos@school.edu','Facilities Feedback','Prompt action on room cleaning','Appreciate the quick response to our restroom cleaning report last week.',4,NULL,NULL,NULL,'2026-11-03 22:32:21'),(113,1,2,'Juan Dela Cruz','juan.delacruz@student.com','Resolution Rating','Resolution of SCF-2026-002','The food warmers were fixed within a day. Thank you!',5,NULL,NULL,NULL,'2026-11-04 18:32:21'),(114,6,6,'Mark Villanueva','mark.villanueva@school.edu','Resolution Rating','Resolution of SCF-2026-006','It was fixed, but it took almost four days and affected my grade computation.',2,NULL,NULL,NULL,'2026-11-04 13:32:21'),(115,9,NULL,'Mcmc Reambonanza','besasmcmc@gmail.com','System Feedback','Test Feedback','Feedback Test',5,NULL,NULL,NULL,'2026-11-09 18:48:46'),(230,14,NULL,'Rodel Santiago Jr.','rodel.santiago@example.com','Facilities Feedback','SAMPLE FEEDBACK','SAMPLE',4,NULL,NULL,NULL,'2026-11-10 22:18:13'),(231,12,NULL,'Shiela Marie Cabrera','shiela.cabrera@example.com','System Feedback','admin gwapo','TEST',4,NULL,NULL,NULL,'2026-11-10 22:18:58'),(232,12,NULL,'Shiela Marie Cabrera','shiela.cabrera@example.com','Academic Feedback','CUTE','KADUGAY',3,'Hello',1,'2026-11-10 22:19:34','2026-11-10 22:19:20');
